const histories=new WeakMap();
const restored=new WeakSet();
let pendingEditorId='';
let saveTimer=0;
function activeEditor(){return document.querySelector('#editor[contenteditable="true"]')??null}
function historyFor(editor){let state=histories.get(editor);if(!state){state={snapshots:[editor.innerHTML],index:0};histories.set(editor,state)}return state}
function remember(editor){const state=historyFor(editor),html=editor.innerHTML;if(state.snapshots[state.index]===html)return;state.snapshots.splice(state.index+1);state.snapshots.push(html);if(state.snapshots.length>80)state.snapshots.shift();state.index=state.snapshots.length-1}
function undo(editor){const state=historyFor(editor);if(state.index<=0)return;state.index-=1;editor.innerHTML=state.snapshots[state.index];editor.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'historyUndo'}))}
function currentRange(editor){const selection=window.getSelection();if(!selection?.rangeCount)return null;const range=selection.getRangeAt(0),container=range.commonAncestorContainer.nodeType===Node.ELEMENT_NODE?range.commonAncestorContainer:range.commonAncestorContainer.parentElement;return container&&editor.contains(container)?range:null}
function restoreSelection(range){const selection=window.getSelection();if(!selection)return;selection.removeAllRanges();selection.addRange(range)}
function wrapBold(editor){const range=currentRange(editor);if(!range||range.collapsed)return;const strong=document.createElement('strong');strong.append(range.extractContents());range.insertNode(strong);const next=document.createRange();next.selectNodeContents(strong);restoreSelection(next)}
function makeList(editor){const range=currentRange(editor);if(!range)return;if(range.collapsed){const node=range.startContainer.nodeType===Node.ELEMENT_NODE?range.startContainer:range.startContainer.parentElement,block=node?.closest('p,div');if(!block||!editor.contains(block))return;const list=document.createElement('ul'),item=document.createElement('li');while(block.firstChild)item.append(block.firstChild);list.append(item);block.replaceWith(list);const next=document.createRange();next.selectNodeContents(item);next.collapse(false);restoreSelection(next);return}const lines=range.toString().split(/\n+/).map(line=>line.trim()).filter(Boolean);if(!lines.length)return;const list=document.createElement('ul');for(const line of lines){const item=document.createElement('li');item.textContent=line;list.append(item)}range.deleteContents();range.insertNode(list);const next=document.createRange();next.selectNodeContents(list);next.collapse(false);restoreSelection(next)}
function runCommand(editor,command){if(command==='bold')wrapBold(editor);else if(command==='insertUnorderedList')makeList(editor);else if(command==='undo'){undo(editor);return}remember(editor);editor.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'format'}))}
function openNotebook(scope='guest'){return new Promise((resolve,reject)=>{const request=indexedDB.open(`seeker-notebook-3:${scope}`,1);request.onupgradeneeded=()=>{for(const name of['records','drafts','media','queue','meta'])if(!request.result.objectStoreNames.contains(name))request.result.createObjectStore(name,{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
function readRecord(db,store,id){return new Promise((resolve,reject)=>{const request=db.transaction(store).objectStore(store).get(id);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
function writeRecord(db,store,value){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function deleteRecord(db,store,id){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function currentScope(){const guest=await openNotebook('guest');try{const meta=await readRecord(guest,'meta','active-account');return meta?.value||'guest'}finally{guest.close()}}
async function withCurrentNotebook(run){const db=await openNotebook(await currentScope());try{return await run(db)}finally{db.close()}}
function draftStatus(editor){const modal=editor.closest('.editor-modal');let status=modal?.querySelector('[data-editor-draft-state]');if(!status){status=document.createElement('p');status.className='muted-copy';status.dataset.editorDraftState='';status.setAttribute('aria-live','polite');status.style.margin='8px 0 0';status.style.fontSize='12px';editor.insertAdjacentElement('afterend',status)}return status}
async function restoreDraft(editor){if(restored.has(editor)||!pendingEditorId)return;restored.add(editor);editor.dataset.recordId=pendingEditorId;const draft=await withCurrentNotebook(db=>readRecord(db,'drafts',pendingEditorId)).catch(()=>undefined);if(!draft?.content||draft.content===editor.innerHTML)return;editor.innerHTML=draft.content;histories.set(editor,{snapshots:[draft.content],index:0});draftStatus(editor).textContent='Восстановлен несохранённый черновик'}
function scheduleDraft(editor){const id=editor.dataset.recordId||pendingEditorId;if(!id)return;clearTimeout(saveTimer);draftStatus(editor).textContent='Сохраняем черновик…';saveTimer=window.setTimeout(async()=>{const draft={id,content:editor.innerHTML,updated_at:new Date().toISOString()};try{await withCurrentNotebook(db=>writeRecord(db,'drafts',draft));draftStatus(editor).textContent='Черновик сохранён на устройстве'}catch{draftStatus(editor).textContent='Не удалось сохранить черновик'}},500)}
async function discardDraft(editor){const id=editor.dataset.recordId||pendingEditorId;if(!id)return;clearTimeout(saveTimer);await withCurrentNotebook(db=>deleteRecord(db,'drafts',id)).catch(()=>undefined)}
function insertPlainText(editor,text){const range=currentRange(editor);if(!range)return;range.deleteContents();const fragment=document.createDocumentFragment(),lines=text.replace(/\r/g,'').split('\n');lines.forEach((line,index)=>{if(index)fragment.append(document.createElement('br'));fragment.append(document.createTextNode(line))});const last=fragment.lastChild;range.insertNode(fragment);if(last){const next=document.createRange();next.setStartAfter(last);next.collapse(true);restoreSelection(next)}editor.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertFromPaste'}))}
document.addEventListener('click',event=>{const target=event.target;if(!(target instanceof Element))return;const edit=target.closest('[data-action="edit-section"]');if(edit?.dataset.id)pendingEditorId=edit.dataset.id;const cancel=target.closest('.editor-modal .form-actions [data-action="close-overlay"]');if(cancel){const editor=activeEditor();if(editor)void discardDraft(editor)}const control=target.closest('[data-command]');if(!control)return;const editor=activeEditor();if(!editor)return;event.preventDefault();event.stopImmediatePropagation();editor.focus({preventScroll:true});runCommand(editor,control.dataset.command||'')},true);
document.addEventListener('focusin',event=>{const target=event.target;if(target instanceof HTMLElement&&target.matches('#editor[contenteditable="true"]')){historyFor(target);void restoreDraft(target)}});
document.addEventListener('input',event=>{const target=event.target;if(target instanceof HTMLElement&&target.matches('#editor[contenteditable="true"]')){remember(target);scheduleDraft(target)}},true);
document.addEventListener('paste',event=>{const target=event.target;if(!(target instanceof HTMLElement)||!target.matches('#editor[contenteditable="true"]'))return;event.preventDefault();insertPlainText(target,event.clipboardData?.getData('text/plain')||'')},true);
document.addEventListener('keydown',event=>{const editor=activeEditor();if(!editor||event.target!==editor||!(event.metaKey||event.ctrlKey))return;const key=event.key.toLowerCase();if(key==='b'){event.preventDefault();runCommand(editor,'bold')}else if(key==='z'&&!event.shiftKey){event.preventDefault();runCommand(editor,'undo')}},true);
